#!/bin/sh
# Regenerate paper/eval-numbers.tex --- every figure Section 8 quotes.
#
# No number in the paper's evaluation is typed into its prose: each is a
# \newcommand in the generated file. The suites print one
#
#     #eval KEY VALUE
#
# line per figure and this script sums by key across all of them, so a
# counter several suites keep (the emitter's classification) carries no
# suite in its name, while a counter one suite keeps is summed trivially.
#
# The figures are reproducible: both random generators are seeded
# (Random.State.make [| 7 |] in test_simplifier, Random.init 42 in
# test_layouts), so a rerun on the same tree gives the same numbers.
#
# A key the paper needs but no suite emits is an error, so the paper can
# never keep a macro that nothing measures any more.
#
# With --check the file is not rewritten: it is regenerated and compared
# with the committed one, and a difference is a failure. That is the form
# to run in CI --- it is what catches an evaluation whose prose has
# drifted away from the code it describes.
set -eu

check=false
case "${1-}" in
  --check) check=true ;;
  "") ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
cd "$root"

dune build @all

generated=$(mktemp)
trap 'rm -f "$generated"' EXIT

# Run the executables directly rather than through `dune test`: this is a
# measurement, and it should not be served from dune's cache.
raw=$(for exe in _build/default/test/test_*.exe; do "$exe"; done)

# The two figures that are not a test's own output.
lib_lines=$(cat lib/*.ml | wc -l)
lib_mli_lines=$(cat lib/*.mli | wc -l)
test_lines=$(cat test/*.ml | wc -l)
coq_lines=$(cat coq/*.v | wc -l)

printf '%s\n' "$raw" | awk \
  -v lib_lines="$lib_lines" \
  -v lib_mli_lines="$lib_mli_lines" \
  -v test_lines="$test_lines" \
  -v coq_lines="$coq_lines" '
# 186293 -> 186{,}293, the thousands separator the paper writes by hand
function group(v,   t, r) {
  t = v ""
  r = ""
  while (length(t) > 3) {
    r = "{,}" substr(t, length(t) - 2) r
    t = substr(t, 1, length(t) - 3)
  }
  return t r
}

BEGIN {
  order = "lib.lines lib.mli_lines test.lines coq.lines " \
          "emit.total emit.affine emit.digits emit.pipeline " \
          "dense.random " \
          "pairs.trials pairs.affine pairs.strided " \
          "pairs.ops_pipeline pairs.ops_emitted " \
          "chains.trials chains.affine chains.strided " \
          "swizzled.trials swizzled.strided swizzled.strided_unswizzled " \
          "axis.functions axis.strided axis.constructed " \
          "extracted.maps extracted.strided " \
          "sm90.coords"

  macro["lib.lines"]                   = "evalLibLines"
  macro["lib.mli_lines"]               = "evalLibMliLines"
  macro["test.lines"]                  = "evalTestLines"
  macro["coq.lines"]                   = "evalCoqLines"
  macro["emit.total"]                  = "evalLayouts"
  macro["emit.affine"]                 = "evalLayoutsAffine"
  macro["emit.digits"]                 = "evalLayoutsRefined"
  macro["emit.pipeline"]               = "evalLayoutsPipeline"
  macro["dense.random"]                = "evalDenseRandom"
  macro["pairs.trials"]                = "evalPairs"
  macro["pairs.affine"]                = "evalPairsAffine"
  macro["pairs.strided"]               = "evalPairsStrided"
  macro["pairs.ops_pipeline"]          = "evalPairsOpsPipeline"
  macro["pairs.ops_emitted"]           = "evalPairsOpsEmitted"
  macro["chains.trials"]               = "evalChains"
  macro["chains.affine"]               = "evalChainsAffine"
  macro["chains.strided"]              = "evalChainsStrided"
  macro["swizzled.trials"]             = "evalSwizzled"
  macro["swizzled.strided"]            = "evalSwizzledStrided"
  macro["swizzled.strided_unswizzled"] = "evalSwizzledPlainStrided"
  macro["axis.functions"]              = "evalAxisFunctions"
  macro["axis.strided"]                = "evalAxisStrided"
  macro["axis.constructed"]            = "evalAxisConstructed"
  macro["extracted.maps"]              = "evalExtractedMaps"
  macro["extracted.strided"]           = "evalExtractedStrided"
  macro["sm90.coords"]                 = "evalSmNinetyCoords"
}

/^#eval / { sum[$2] += $3; seen[$2] = 1 }

END {
  sum["lib.lines"] = lib_lines;         seen["lib.lines"] = 1
  sum["lib.mli_lines"] = lib_mli_lines; seen["lib.mli_lines"] = 1
  sum["test.lines"] = test_lines;       seen["test.lines"] = 1
  sum["coq.lines"] = coq_lines;         seen["coq.lines"] = 1

  n = split(order, keys, " ")
  for (i = 1; i <= n; i++)
    if (!(keys[i] in seen)) {
      printf("eval.sh: no test emitted %s\n", keys[i]) > "/dev/stderr"
      missing = 1
    }
  if (missing) exit 1

  print "% Generated by paper/eval.sh from a run of the test suite."
  print "% Do not edit: rerun the script instead."
  for (i = 1; i <= n; i++) {
    k = keys[i]
    printf("\\newcommand{\\%s}{%s}\n", macro[k], group(sum[k]))
  }
}
' > "$generated"

if $check; then
  if cmp -s "$generated" paper/eval-numbers.tex; then
    echo "paper/eval-numbers.tex is up to date"
  else
    echo "paper/eval-numbers.tex is stale; rerun paper/eval.sh" >&2
    diff -u paper/eval-numbers.tex "$generated" >&2 || true
    exit 1
  fi
else
  mv "$generated" paper/eval-numbers.tex
  echo "wrote paper/eval-numbers.tex"
fi
